mutation CreatePost($input: CreatePostInput!) {
  createPost(input: $input) {
    __typename
    ... on PostActionSuccess {
      post {
        id
        text
        status
        dueAt
        sentAt
        channelId
      }
    }
    ... on MutationError {
      message
    }
  }
}

mutation CreateIdea($input: CreateIdeaInput!) {
  createIdea(input: $input) {
    __typename
    ... on IdeaResponse {
      idea {
        id
        organizationId
        groupId
        createdAt
        updatedAt
        content {
          title
          text
          media { url type alt }
          tags { id name color }
        }
      }
      refreshIdeas
    }
    ... on MutationError {
      message
    }
  }
}
